// Bind a disposable historical fixture to its own immutable parent, not to a
// mutable preview index regenerated by an earlier command in the same suite.
import assert from 'node:assert/strict';
import {readFileSync,writeFileSync} from 'node:fs';
import {join,relative,resolve} from 'node:path';
import {tmpdir} from 'node:os';
import {root} from '../../scripts/source-first/build.mjs';
import {digest} from '../../scripts/source-first/model.mjs';
export function bindHistoricalParentInventory(base,parent,parentFile){
  const rel=relative(resolve(tmpdir()),resolve(base));
  assert.ok(rel&&!rel.startsWith('..')&&resolve(base)!==resolve(root),'Disposable temporary fixture required');
  assert.equal(parentFile,`.content-work/release-v6/${parent.planHash}/manifest.json`);
  const stored=JSON.parse(readFileSync(join(base,parentFile),'utf8'));
  assert.deepEqual(stored,parent);const {planHash,...body}=stored;assert.equal(digest(body),planHash);
  const file=join(base,'.audit/source-first-v5/release-v6/inventory.json');
  const inventory=JSON.parse(readFileSync(file,'utf8'));
  writeFileSync(file,JSON.stringify({...inventory,planHash:parent.planHash,manifest:parentFile},null,2)+'\n');
}
